import mockTrie from '../../mocks/mockTrie.json';
import { computeRootFromBlobs, nonMembershipByKey, proofByKey } from '../proof';
import type { BlobRow } from '../proof';

// Generated by trezorlib; the same encoded values are checked against the Rust trie.
const BLOBS: BlobRow[] = mockTrie.leaves;

describe('path-compressed trie parity with trezorlib and the Rust default value encoding', () => {
    it('computeRootFromBlobs matches the reference root', () => {
        expect(computeRootFromBlobs(BLOBS)).toBe(mockTrie.root);
    });

    it('proofByKey matches the reference membership proof', () => {
        const proof = proofByKey(BLOBS, mockTrie.memberKey);
        expect(proof).toEqual(mockTrie.memberProof);
        proof.forEach(element => expect(element).toHaveLength(68));
    });

    it('nonMembershipByKey matches the reference witness and proof', () => {
        const proof = nonMembershipByKey(BLOBS, mockTrie.absentKey);
        expect(proof.witnessEntryKeyHex).toBe(mockTrie.witnessKey);
        expect(proof.witnessCommitHex).toBe(mockTrie.witnessCommit);
        expect(proof.proof).toEqual(mockTrie.nonMemberProof);
    });
});
